```sql
SELECT T1.`aCL IgM` FROM Examination AS T1 INNER JOIN Patient AS T2 ON T1.ID = T2.ID WHERE T2.Description = '1994-02-19' AND T1.`Examination Date` = '1993/11/12' AND T2.Diagnosis = 'SLE';
```

```sql
SELECT COUNT(*) FROM Laboratory WHERE ID = 57266 AND (UA > 8.0 AND T1.SEX = 'M' OR UA > 6.5 AND T1.SEX = 'F');
```

```sql
SELECT T2.Diagnosis FROM Laboratory AS T1 INNER JOIN Patient AS T2 ON T1.ID = T2.ID WHERE T1.GPT > 60 ORDER BY T2.Birthday ASC;
```

```sql
SELECT T1.SEX, GROUP_CONCAT(DISTINCT T1.ID) AS List FROM Patient AS T1 INNER JOIN Laboratory AS T2 ON T1.ID = T2.ID WHERE T2.`T-BIL` >= 2.0 GROUP BY T1.SEX;
```

```sql
SELECT ID, SEX FROM Patient WHERE Diagnosis = 'SLE' AND HGB BETWEEN 10 AND 17 ORDER BY Birthday DESC LIMIT 1;
```

```sql
SELECT Diagnosis FROM Examination WHERE `aCL IgM` <= 40 OR `aCL IgM` >= 400 GROUP BY Diagnosis ORDER BY COUNT(Diagnosis) DESC LIMIT 1;
```

```sql
SELECT COUNT(DISTINCT T1.ID) FROM Patient AS T1 INNER JOIN Examination AS T2 ON T1.ID = T2.ID WHERE T1.Sex = 'M' AND T2.CENTROMEA IN ('-', '+-') AND T2.SSB IN ('-', '+-');
```

```sql
SELECT COUNT(circuitId) FROM circuits WHERE country = 'Australia' AND location = 'Adelaide';
```

```sql
SELECT id FROM publisher WHERE publisher_name = 'Star Trek';
```

```sql
SELECT DISTINCT T2.power_name FROM superhero AS T1 INNER JOIN hero_power AS T3 ON T1.id = T3.hero_id INNER JOIN superpower AS T2 ON T3.power_id = T2.id WHERE T1.gender_id = 1 LIMIT 5;
```

```sql
SELECT COUNT(DISTINCT power_id) FROM hero_power WHERE hero_id = (SELECT id FROM superhero WHERE superhero_name = 'Amazo');
```

```sql
SELECT superhero_name FROM superhero WHERE eye_colour_id = (SELECT id FROM colour WHERE colour = 'Black') AND hair_colour_id = (SELECT id FROM colour WHERE colour = 'Black');
```

```sql
SELECT T1.publisher_name FROM publisher AS T1 INNER JOIN superhero AS T2 ON T1.id = T2.publisher_id WHERE T2.superhero_name IN ('Hawkman', 'Karate Kid', 'Speedy');
```

```sql
SELECT T2.colour FROM superhero AS T1 INNER JOIN colour AS T2 ON T1.eye_colour_id = T2.id WHERE T1.full_name = 'Karen Beecher-Duncan';
```

```sql
SELECT superhero_name FROM superhero WHERE id IN (SELECT hero_id FROM hero_power WHERE power_id = (SELECT id FROM superpower WHERE power_name = 'Wind Control')) ORDER BY superhero_name ASC;
```

```sql
SELECT manaCost FROM cards WHERE layout = 'normal' AND frameVersion = 2003 AND borderColor = 'black' AND availability = 'mtgo,paper';
```

```sql
SELECT CAST(SUM(CASE WHEN DOC = 54 THEN 1 ELSE 0 END) AS REAL) / SUM(CASE WHEN DOC = 52 THEN 1 ELSE 0 END) FROM schools WHERE County = 'Orange';
```
